import{_ as e,c as t,o as l,a2 as o}from"./chunks/framework.D30IVGRC.js";const u=JSON.parse('{"title":"PaddleXOCR - Python印章识别与文档信息抽取","description":"基于PaddleOCR的印章识别和文档信息抽取系统","frontmatter":{"layout":"home","title":"PaddleXOCR - Python印章识别与文档信息抽取","description":"基于PaddleOCR的印章识别和文档信息抽取系统","head":[["meta",{"name":"keywords","content":"OCR, 印章识别, 文档信息抽取, PaddleOCR, 表格识别"}],["meta",{"name":"author","content":"FullStack团队"}],["meta",{"name":"copyright","content":"FullStack Monorepo项目"}]],"hero":{"name":"PaddleXOCR","text":"印章识别与文档信息抽取","tagline":"基于PaddleOCR的高性能文档信息处理系统","image":{"src":"/images/ocr.png","alt":"OCR图像"},"actions":[{"theme":"brand","text":"技术详情","link":"./docs/overview.md"},{"theme":"alt","text":"快速开始","link":"./docs/quickstart.md"}]},"features":[{"icon":"🧩","title":"高精度识别","details":"支持文本、表格、印章等多种元素的高精度识别，适用于多样化文档场景"},{"icon":"🌐","title":"多模块架构","details":"包含版面区域检测、文本检测与识别、表格结构识别、印章文本检测等多个协同工作的模块"},{"icon":"📦","title":"灵活部署","details":"支持服务器端和移动端模型，可根据实际需求选择性能与精度的平衡"},{"icon":"🔄","title":"可定制化","details":"支持模型微调与训练，可针对特定场景优化识别效果"}]},"headers":[],"relativePath":"apps-python/ocr-vlm/README.md","filePath":"apps-python/ocr-vlm/README.md","lastUpdated":1746462094000}'),i={name:"apps-python/ocr-vlm/README.md"};function r(n,a,d,s,c,h){return l(),t("div",null,a[0]||(a[0]=[o('<h1 id="paddlexocr-印章识别与文档信息抽取" tabindex="-1">PaddleXOCR 印章识别与文档信息抽取 <a class="header-anchor" href="#paddlexocr-印章识别与文档信息抽取" aria-label="Permalink to &quot;PaddleXOCR 印章识别与文档信息抽取&quot;">​</a></h1><h2 id="项目概述" tabindex="-1">项目概述 <a class="header-anchor" href="#项目概述" aria-label="Permalink to &quot;项目概述&quot;">​</a></h2><p>PaddleXOCR是一套基于飞桨PaddlePaddle的文档场景信息抽取系统，针对文档中的文字、表格、印章等元素进行精准识别和信息提取。本项目专注于解决企业和组织在数字化转型过程中对文档信息处理的高精度需求。</p><h2 id="核心功能" tabindex="-1">核心功能 <a class="header-anchor" href="#核心功能" aria-label="Permalink to &quot;核心功能&quot;">​</a></h2><ul><li><strong>印章文本检测与识别</strong>：高精度识别文档中的印章文字信息</li><li><strong>版面区域检测</strong>：识别文档中的不同区域类型（文本、表格、图片等）</li><li><strong>表格结构识别</strong>：将图像中的表格转换为可编辑的结构化数据</li><li><strong>文本检测与识别</strong>：精准定位和识别文档中的文字内容</li><li><strong>文档图像方向分类</strong>：自动识别并校正文档方向，提升后续处理准确性</li></ul><h2 id="技术特点" tabindex="-1">技术特点 <a class="header-anchor" href="#技术特点" aria-label="Permalink to &quot;技术特点&quot;">​</a></h2><ul><li><strong>模块化架构</strong>：各功能模块独立且协同工作，提供完整的文档处理流程</li><li><strong>多模型支持</strong>：提供服务器端和移动端不同性能需求的模型选择</li><li><strong>高性能实现</strong>：优化的推理速度和资源占用，适用于大规模文档处理</li><li><strong>精度与效率平衡</strong>：在不同场景下可根据需求平衡识别精度和处理效率</li></ul><h2 id="应用场景" tabindex="-1">应用场景 <a class="header-anchor" href="#应用场景" aria-label="Permalink to &quot;应用场景&quot;">​</a></h2><ul><li><strong>金融合同审核</strong>：自动从合同文档中提取关键条款和信息</li><li><strong>政府文件处理</strong>：高效处理政务文件，提取结构化数据</li><li><strong>企业档案管理</strong>：对大量历史文档进行数字化整理和信息提取</li><li><strong>发票报销审核</strong>：自动识别发票信息和印章有效性</li></ul><h2 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h2><p>请参考<a href="./docs/quickstart">快速开始文档</a>了解如何安装和使用PaddleXOCR。</p><h2 id="技术文档" tabindex="-1">技术文档 <a class="header-anchor" href="#技术文档" aria-label="Permalink to &quot;技术文档&quot;">​</a></h2><ul><li><a href="./docs/installation">环境安装</a></li><li><a href="./docs/models">模型列表及对比</a></li><li><a href="./docs/architecture">架构设计</a></li><li><a href="./docs/training">模型训练指南</a></li><li><a href="./docs/labeling">数据标注工具</a></li><li><a href="./docs/deployment">模型部署指南</a></li><li><a href="./docs/image_extraction">DOCX图片提取</a></li><li><a href="./docs/api">API接口</a></li></ul><h2 id="许可证" tabindex="-1">许可证 <a class="header-anchor" href="#许可证" aria-label="Permalink to &quot;许可证&quot;">​</a></h2><p>本项目基于Apache 2.0许可证开源。</p>',15)]))}const p=e(i,[["render",r]]);export{u as __pageData,p as default};
